# -*- coding: utf-8 -*-
"""One integrated scaling/cross-chain chapter; original bilingual explanations."""
from html import escape

def chapter(lang):
    t=lambda en,zh:zh if lang=='zh' else en
    p=lambda *xs:''.join('<p>'+x+'</p>' for x in xs)
    code=lambda x:'<pre><code>'+escape(x)+'</code></pre>'
    def table(headers,rows):
        return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    rows=[]
    def add(ident,title,intro,body,refs,viz=None):rows.append((ident,title,intro,body,refs,viz))
    add('rollups',t('L2 moves work; the settlement path defines the guarantee','L2 迁移工作，结算路径决定保障'),t('Ethereum rollups and Bitcoin payment channels are two different scaling models.','Ethereum Rollup 与 Bitcoin 支付通道是两种不同扩容模型。'),p(t('A rollup executes a separate state machine and publishes data and state commitments to Ethereum. L1 contracts enforce its specified proof and exit rules. The sequencer orders transactions; a batcher publishes data; independent nodes reconstruct the execution. These jobs can be operated by different components. A fast sequencer receipt is an early observation, not automatically final L1 settlement.','Rollup 执行独立状态机，将数据及状态承诺发布到 Ethereum，由 L1 合约执行特定证明及退出规则。排序器排列交易，Batcher 发布数据，独立节点重建执行。这些职责可以由不同组件承担。排序器的快速回执是早期观察，不自动等于 L1 最终结算。'))+table([t('Model','模型'),t('What moves off L1','移出 L1 的工作'),t('What must be inspected','需要检查的条件')],[('Ethereum rollup',t('General execution and application state','通用执行与应用状态'),t('L1 data, proof system, bridge, upgrade powers','L1 数据、证明系统、桥及升级权限')),('Lightning',t('Updates between funded channel participants','已注资通道参与者之间的更新'),t('Liquidity, latest state, deadlines and Bitcoin enforcement','流动性、最新状态、期限及 Bitcoin 执行')),('Sidechain / validium',t('Separate execution; possibly separate data availability','独立执行，可能使用独立数据可用性'),t('Own validators or external DA assumptions; not identical to a rollup','自身验证者或外部 DA 假设，不等同于 Rollup'))])+p(t('An L2 label is not a complete security description. Separate execution correctness, data availability, liveness and control. Lightning is already a deployed network; “recent developments” below concern its evolving protocols and applications, not a claim that payment channels were invented in 2026.','L2 标签不是完整安全描述。应分开执行正确性、数据可用性、活性及控制权。闪电网络早已部署，后文“近期动向”指持续发展的协议及应用，并不是说支付通道在 2026 年才出现。')),('scaling','op-batcher','op-derivation','bolt2'),'scaling')
    add('proofs',t('Optimistic and validity proofs enforce different acceptance rules','Optimistic 与有效性证明采用不同接受规则'),t('A state root is a commitment; it is not a proof that the transition is correct.','状态根是一项承诺，不是状态转换正确的证明。'),table([t('Question','问题'),t('Optimistic rollup','Optimistic Rollup'),t('Validity-proof rollup','有效性证明 Rollup')],[(t('Proposed result','提议结果'),t('An assertion that remains disputable','仍可被争议的断言'),t('A result accompanied by an execution-validity proof','附执行有效性证明的结果')),(t('Enforcement','执行约束'),t('A challenger disputes an incorrect transition; an L1 game resolves it','挑战者质疑错误转换，L1 争议游戏裁定'),t('An L1 verifier checks a proof for the specified program and public inputs','L1 验证器检查特定程序及公开输入的证明')),(t('Exit timing','退出时间'),t('Dispute resolution and deployment-specific maturity delays','争议解决及部署特定成熟延迟'),t('Proof generation, submission, acceptance and bridge conditions','生成、提交、接受证明及桥条件')),(t('Additional assumptions','其他假设'),t('Available data and a timely honest challenger under the configured rules','可用数据、按配置规则及时行动的诚实挑战者'),t('Sound proof system, correct circuits/VM, available data and valid bridge logic','可靠证明系统、正确电路 / VM、可用数据及正确桥逻辑'))])+p(t('In an interactive fault-proof design, execution traces can be narrowed down to a disputed instruction that L1 can check. A zkVM/zkEVM instead turns the chosen execution into constraints and generates a succinct proof. “Zero knowledge” in a rollup name does not mean transaction data or balances are private. A proof establishes the encoded statement, not every property of the application.','交互式故障证明可将执行轨迹收缩到 L1 能检查的争议指令。zkVM / zkEVM 则将所选执行转换为约束并生成简洁证明。Rollup 名称中的“零知识”不意味着交易数据或余额私密。证明建立的是被编码的陈述，不是应用的全部性质。'),t('OP Stack’s fault-proof bridge separates proveWithdrawalTransaction from finalizeWithdrawalTransaction. Game outcome, proof maturity, additional delays and Guardian controls matter. Do not hard-code “all L2 withdrawals take seven days” or “ZK exits are instant.” A fast liquidity-provider exit adds its own pricing and counterparty mechanism.','OP Stack 故障证明桥区分 proveWithdrawalTransaction 与 finalizeWithdrawalTransaction。争议结果、证明成熟时间、额外延迟及 Guardian 权限都重要。不能写死“所有 L2 提现需七天”或“ZK 提现即时完成”。流动性提供方的快速退出还引入自己的定价及交易对手机制。')),('optimistic','validity','op-withdraw','nitro'),'scale-proofs')
    add('blobs',t('Blobs and PeerDAS scale the data layer, not the EVM instruction rate','Blob 与 PeerDAS 扩展数据层，不直接提高 EVM 指令速率'),t('Data availability and execution validity answer different questions.','数据可用性与执行有效性回答不同问题。'),p(t('EIP-4844 introduced blob-carrying transactions: a blob contains 4096 field elements, occupying 131072 bytes, and has a separate blob-gas fee market. The EVM sees versioned hashes of blob commitments rather than arbitrary access to the blob bytes. Rollups post compressed data through this channel; normal execution gas is still a separate cost.','EIP-4844 引入携带 Blob 的交易：一个 Blob 包含 4096 个域元素，占 131072 字节，并具有独立 Blob Gas 费用市场。EVM 看到的是 Blob 承诺的带版本哈希，不能任意读取 Blob 字节。Rollup 通过该通道发布压缩数据，普通执行 Gas 仍是独立成本。'),t('Blob availability is temporary, historically around 18 days under the original retention window. It is not permanent application storage. Rollup node operators and archival services must retain the history they need for reconstruction; a commitment alone cannot regenerate missing data.','Blob 可用性是临时的，原始保留窗口约为 18 天，并非永久应用存储。Rollup 节点运营者及归档服务须保存重建所需历史；只有承诺不能恢复丢失数据。'),t('PeerDAS, deployed with Fusaka, erasure-codes blob data into columns. Nodes custody assigned columns and sample availability instead of every node downloading every full blob. This allows blob capacity to rise with manageable per-node load. It does not verify rollup execution or make bandwidth free. Blob-parameter-only upgrades can adjust target/max counts; these are coordinated network changes, not automatic unlimited throughput.','随 Fusaka 部署的 PeerDAS 将 Blob 数据纠删编码成列，节点托管所分配列并采样可用性，不再要求每个节点下载所有完整 Blob。这允许在可控单节点负载下提高容量，但不验证 Rollup 执行，也不让带宽免费。仅改 Blob 参数的升级可调整目标 / 最大数量；它们是协调网络变更，不是自动无限吞吐。')),('eip4844','eip7594','fusaka'))
    add('implementations',t('Read an implementation by component and deployment','按组件及部署阅读实现'),t('A shared framework does not imply identical data modes, governance or finality.','共享框架不意味着相同数据模式、治理或最终性。'),table([t('Example','例子'),t('Implementation path','实现路径'),t('Useful question','适用问题')],[('OP Stack',t('Rollup node + execution engine; batcher; assertions/fault games; L1 portal','Rollup 节点 + 执行引擎、Batcher、断言 / 故障游戏、L1 Portal'),t('Can I derive the same L2 blocks from L1 inputs, and which game governs this portal?','能否从 L1 输入派生相同 L2 区块，此 Portal 使用哪种争议游戏？')),('Arbitrum Nitro',t('Deterministic execution and a proving representation; BoLD dispute machinery','确定性执行及证明表示、BoLD 争议机制'),t('Which execution and DA configuration does this chain use?','此链采用哪种执行及 DA 配置？')),('ZKsync',t('Execution, batch commitments, proving and L1 verification','执行、批次承诺、证明生成及 L1 验证'),t('Which VM/prover version and settlement/DA mode apply here?','这里适用哪个 VM / 证明器版本及结算 / DA 模式？'))])+p(t('Developer workflow: choose the actual chain and test network → check chain ID and RPC → compile for its supported VM/EVM target → deploy and inspect receipts → test bridge messages and exits. EVM compatibility lets familiar Solidity tools carry over, but precompiles, fee accounting, transaction types and cross-domain calls can differ. A Hardhat execution on chain 31337 does not simulate a real rollup’s data publication or withdrawal contracts.','开发流程：选择实际链及测试网络 → 核对 Chain ID 与 RPC → 按其 VM / EVM 支持目标编译 → 部署及检查回执 → 测试桥消息及退出。EVM 兼容可复用熟悉的 Solidity 工具，但预编译、费用核算、交易类型及跨域调用仍可能不同。在链 31337 的 Hardhat 执行不会模拟真实 Rollup 的数据发布或提现合约。'),t('Study operational failures as part of implementation: stop the sequencer, observe the documented forced-inclusion path, reconstruct state from published inputs, and inspect upgrade/pausing authority. These are protocol-specific experiments, not consequences of choosing an L2 brand.','实现学习还应包括运行故障：停止排序器，观察文档定义的强制包含路径，从已发布输入重建状态，并检查升级 / 暂停权限。这些是协议特定实验，不是选择某 L2 品牌的自动结果。')),('op-derivation','op-batcher','nitro','zksync-rollup'))
    add('lightning',t('Lightning settles enforceable channel states on Bitcoin','闪电网络在 Bitcoin 上结算可执行通道状态'),t('Funding is on-chain; most balance updates remain between participants.','注资在链上，多数余额更新保留在参与者之间。'),p(t('A payment channel commits Bitcoin funds to jointly controlled spending rules. Each side holds signed commitment transactions representing an enforceable state. Normal operation exchanges new commitments and revokes the previous state. In the established revocation-based design, delayed outputs and breach remedies discourage publishing a revoked commitment. The funding output remains the backing; participants do not mine a new Bitcoin block for every payment.','支付通道将 Bitcoin 资金交给共同控制的花费规则。双方持有代表可执行状态的签名承诺交易。正常运行交换新承诺并撤销旧状态。在已采用的撤销式设计中，延迟输出及违约补救约束广播被撤销承诺。注资输出持续提供资金基础，参与者不需为每笔支付挖出新 Bitcoin 区块。'))+code('Teaching example: capacity = 100,000 sat\nInitial: Alice 80,000 | Bob 20,000\nAlice pays Bob 15,000\nUpdated: Alice 65,000 | Bob 35,000\nTotal capacity remains 100,000 sat')+p(t('The example deliberately omits commitment fees, channel reserves, pending HTLCs and dust limits; usable spending capacity is therefore smaller than the simple total in a real channel. A cooperative close agrees on a settlement transaction. A unilateral close uses the enforced commitment/HTLC paths and can require waiting and additional on-chain fees. Lightning changes when settlement work is done; it does not remove the base chain.','例子刻意省略承诺费用、通道储备、待决 HTLC 及粉尘限制，因此真实可花费能力低于简单总量。协作关闭共同签署结算交易；单边关闭走承诺 / HTLC 执行路径，可能需要等待及额外链上费用。闪电网络改变结算工作的发生时机，不移除底层链。')),('bolt2','bolt3'),'ln-channel')
    add('routing',t('HTLCs link several channels without a direct Alice–Carol channel','HTLC 连接多个通道，无需 Alice–Carol 直接通道'),t('Value is forwarded toward the receiver; the preimage travels back.','价值朝接收方转发，原像向后传递。'),p(t('Carol creates a random preimage r and publishes H=SHA256(r) in an invoice. Alice offers Bob an HTLC conditional on revealing r before an expiry; Bob offers Carol a corresponding HTLC with an earlier expiry. Carol reveals r to claim the payment; Bob uses it upstream. The timeout gap gives intermediaries time to enforce their claim if off-chain cooperation stops.','Carol 创建随机原像 r，在发票中发布 H=SHA256(r)。Alice 向 Bob 提供一个在期限前揭示 r 才能领取的 HTLC；Bob 向 Carol 提供对应且更早到期的 HTLC。Carol 揭示 r 领取支付，Bob 再将它用于上游。到期时间差为中间节点在链下协作停止时执行权利留出时间。'),t('BOLT 4 onion payloads let each hop process its forwarding instructions; routing nodes do not receive the whole route in cleartext. They still observe their neighbors and local timing/amount information. This is routing privacy, not a universal anonymity guarantee.','BOLT 4 洋葱载荷让每跳处理自己的转发指令，路由节点不会得到明文完整路径。但仍可观察邻居及局部时间 / 金额。这是路由隐私，不是通用匿名保证。'),t('A BOLT 11 invoice can carry the payment hash, amount, expiry and other routing/payment fields. Its payment_secret is not the secret preimage r. A valid invoice does not demonstrate that a usable route exists, and an invoice expiry is distinct from the individual HTLC on-chain deadlines.','BOLT 11 发票可携带支付哈希、金额、有效期及其他路由 / 支付字段。payment_secret 不是秘密原像 r。有效发票不证明存在可用路径，发票有效期也不同于各 HTLC 的链上期限。')),('bolt4','bolt11','bolt3'),'ln-htlc')
    add('liquidity',t('Liquidity direction and operational state determine usability','流动性方向及运行状态决定可用性'),t('Channel capacity is not the amount that can be sent in every direction.','通道容量不是每个方向都能发送的金额。'),p(t('A 100,000-sat channel with 80,000 on Alice’s side does not give Bob 100,000 sat of outbound liquidity. Receiving requires inbound liquidity from the peer side. On an Alice → Bob → Carol route, Bob’s channel to Carol can be the bottleneck even if Bob has ample balance elsewhere. Rebalancing, swaps, opening channels and liquidity services change allocation and can add fees or service dependencies.','一个容量 100000 sat、Alice 侧占 80000 的通道不会给 Bob 100000 sat 出站流动性。接收需要对端一侧的入站流动性。Alice → Bob → Carol 路径上，Bob 到 Carol 的通道可能成为瓶颈，即使 Bob 在别处有充足余额。再平衡、兑换、开通道及流动性服务改变分配，也可能增加费用或服务依赖。'),t('A noncustodial operator must preserve current channel state and handle enforcement deadlines. Watchtowers can help detect revoked-state breaches while a client is offline, but do not route payments, guarantee all liveness, or replace backups. LND static channel backups support recovery through a closure path; restoring a seed is not the same as reconstructing every latest live channel state.','非托管运营者须保存最新通道状态并处理执行期限。Watchtower 可在客户端离线期间帮助检测被撤销状态的违约，但不负责支付路由、不保证全部活性，也不替代备份。LND 静态通道备份通过关闭路径支持恢复；恢复种子不同于重建所有通道的最新运行状态。'),t('A custodial wallet can hide this complexity by operating channels for users, but then the user has a claim on its operator rather than independent control of those channel keys. Evaluate custody separately from the fact that a service uses Lightning.','托管钱包可通过替用户运行通道来隐藏复杂度，但用户此时依赖运营者，而非独立控制这些通道密钥。应将托管关系与服务是否使用 Lightning 分开评估。')),('ln-liquidity','ln-watchtower','ln-recovery'))
    add('lightning-practice',t('Reproduce the payment lifecycle on a local regtest topology','在本地 Regtest 拓扑复现支付生命周期'),t('Follow a real implementation without using public-network funds.','使用真实实现学习，无需公开网络资金。'),p(t('Polar uses Docker to run Bitcoin Core and Lightning implementations. Create three LND nodes, Alice, Bob and Carol, on a local regtest network. Fund Alice and Bob through Polar’s test-funding controls; open Alice–Bob and Bob–Carol channels and mine enough regtest confirmations. Ensure both forwarding directions have spendable liquidity. Open the node-specific terminals so that RPC/TLS credentials and ports refer to that node.','Polar 使用 Docker 运行 Bitcoin Core 及闪电实现。在本地 Regtest 网络创建三个 LND 节点 Alice、Bob、Carol。通过 Polar 测试注资功能给 Alice、Bob 注资，打开 Alice–Bob 与 Bob–Carol 通道并挖出足够确认。确保两个转发方向具有可花费流动性。打开各节点专用终端，使 RPC / TLS 凭据及端口指向对应节点。'))+code('# Carol node terminal — configured local regtest only\nlncli --network=regtest addinvoice --amt=10000 --memo="local routing lesson"\n\n# Alice node terminal — paste the returned payment_request\nlncli --network=regtest decodepayreq --pay_req="<REGTEST_INVOICE>"\nlncli --network=regtest payinvoice "<REGTEST_INVOICE>"\n\n# Inspect each node and the resulting channel balances\nlncli --network=regtest listchannels\nlncli --network=regtest listpayments')+p(t('Check the decoded amount and expiry, payment status, route, fees and balances. Then disconnect Bob before a new payment, or create insufficient outbound capacity, and compare the failure. Finally cooperatively close a test channel, mine blocks and inspect settlement outputs. Record the installed node versions and negotiated features. These are instructions for a separate Polar environment; the website and its Hardhat ZIP do not launch or emulate LND.','检查解码金额及有效期、支付状态、路径、费用及余额。再在新支付前断开 Bob，或制造出站能力不足，比较失败情况。最后协作关闭测试通道，挖出区块并检查结算输出。记录安装节点版本及协商功能。这是独立 Polar 环境的实验说明；网站及 Hardhat ZIP 不启动或模拟 LND。')),('ln-polar','ln-payment'))
    add('bridges',t('Bridges add a cross-system verification boundary','桥增加跨系统验证边界'),t('Preserve asset identity, message origin and finality across the boundary.','跨边界保留资产身份、消息来源及最终性。'),p(t('A lock/mint bridge escrows an asset on the source chain and creates a representation on the destination; other designs burn/mint or exchange existing liquidity. The receiving contract must authenticate the source event, accepted state and message. A rollup’s canonical bridge, an issuer’s native deployment and a third-party wrapped asset are different objects even when a wallet shows the same ticker.','锁定 / 铸造桥在来源链托管资产，在目标链创建表示；其他设计采用销毁 / 铸造或兑换已有流动性。接收合约须验证来源事件、被接受状态及消息。Rollup 官方桥、发行方原生部署及第三方包装资产是不同对象，即使钱包显示相同简称。'))+table([t('Check','检查'),t('Why it matters','原因')],[(t('Chain + exact contract / asset ID','链 + 精确合约 / 资产 ID'),t('A symbol or familiar address is not a cross-chain asset identity','符号或熟悉地址不等于跨链资产身份')),(t('Origin, nonce and replay protection','来源、Nonce 及重放保护'),t('A valid message must not authorize a different domain or execute twice','有效消息不能授权另一个域或执行两次')),(t('Finality and verification mechanism','最终性及验证机制'),t('Reorganizations, proof rules, committees and multisigs create different failure modes','重组、证明规则、委员会及多签产生不同失效方式')),(t('Upgrade powers and exit route','升级权限及退出路径'),t('A paused/upgraded bridge can change practical control of the representation','暂停 / 升级桥可改变表示资产的实际控制'))])+p(t('Cross-domain calls are normally asynchronous. A completed source transaction does not by itself establish destination execution. Design retries, expiry, refunds and independent status tracking. Sharing an EVM or a rollup framework does not make separate chains one synchronous atomic execution environment.','跨域调用通常异步。来源交易完成本身不证明目标执行。应设计重试、到期、退款及独立状态跟踪。共享 EVM 或 Rollup 框架不会让独立链变成一个同步原子执行环境。')),('bridges','tether-protocols','op-withdraw'))
    add('intents-wallets',t('Intents and smart wallets abstract the workflow, not the trust','意图与智能钱包抽象流程，不消除信任条件'),t('Interoperability is becoming an application interface as well as a bridge mechanism.','互操作正在成为应用接口，同时仍依赖桥机制。'),p(t('An intent specifies an acceptable outcome rather than every execution step: for example, deliver at least 99 units of asset Y on chain B before a deadline in exchange for 100 units of X on chain A. A solver supplies a route or destination liquidity and later settles under the order’s rules. ERC-7683 defines shared cross-chain order/settlement interfaces; it does not itself verify all chains or guarantee solver competition, refunds or settlement safety.','意图指定可接受结果，而不是每个执行步骤。例如以链 A 的 100 单位 X 为代价，在期限前向链 B 交付至少 99 单位 Y。Solver 提供路径或目标流动性，再按订单规则结算。ERC-7683 定义共享跨链订单 / 结算接口，本身不验证所有链，也不保证 Solver 竞争、退款或结算安全。'),t('ERC-4337 adds UserOperations, bundlers, an EntryPoint and optional paymasters. A paymaster can sponsor user gas, but somebody still pays and sponsorship has policies. EIP-7702, deployed in Pectra, lets an EOA delegate execution to selected code persistently. It is not a temporary one-call permission or an ERC-20 allowance; a failed execution does not automatically undo the processed delegation.','ERC-4337 加入 UserOperation、Bundler、EntryPoint 及可选 Paymaster。Paymaster 可代付用户 Gas，但仍有人支付且存在代付策略。随 Pectra 部署的 EIP-7702 允许 EOA 持久委托所选代码执行。它不是临时单次调用权限，也不是 ERC-20 授权；执行失败不会自动撤销已处理委托。'),t('These mechanisms can hide network switching, repeated approvals and gas acquisition from users. Implementation still has to bind chain, recipient, asset, amount, deadline and authorization, and make delegation/recovery powers visible. “One-click” is a user-experience result, not a new consensus guarantee.','这些机制可向用户隐藏切网、重复授权及获取 Gas 的流程，但实现仍须绑定链、接收方、资产、金额、期限及授权，并显示委托 / 恢复权限。“一键”是体验结果，不是新的共识保证。')),('erc7683','erc4337','eip7702','pectra'))
    add('updates',t('A dated Web3 progress snapshot','注明日期的 Web3 进展快照'),t('Reviewed 1 October 2026; deployed features and planned upgrades are distinguished.','复核于 2026 年 10 月 1 日；区分已部署功能与计划升级。'),table([t('Milestone','进展'),t('Verified status','核实状态'),t('Mechanism and ecosystem significance','机制及生态意义')],[('Dencun / EIP-4844',t('Ethereum mainnet, 13 Mar 2024','Ethereum 主网，2024-03-13'),t('Blob data market: a cheaper publication path for rollups','Blob 数据市场：为 Rollup 提供更低成本发布路径')),('Pectra',t('Ethereum mainnet, 7 May 2025','Ethereum 主网，2025-05-07'),t('EOA code delegation and increased blob capacity; wallet UX and DA capacity improve through distinct mechanisms','EOA 代码委托及增加 Blob 容量；钱包体验与 DA 容量通过不同机制改进')),('Fusaka / PeerDAS',t('Ethereum mainnet, 3 Dec 2025','Ethereum 主网，2025-12-03'),t('Column custody/sampling and blob-parameter-only upgrades; grow DA without requiring all nodes to download every full blob','列托管 / 采样及仅改 Blob 参数的升级；扩展 DA 无需所有节点下载每个完整 Blob')),('Taproot Assets v0.8 + SDK',t('Lightning Labs release, 23 Jun 2026','Lightning Labs 发布，2026-06-23'),t('Higher-level asset API, backup/restore and edge-node/RFQ improvements; simplifies multi-asset application implementation','高层资产 API、备份 / 恢复及边缘节点 / RFQ 改进，简化多资产应用实现')),('Glamsterdam',t('17 Sep announcement: Sepolia scheduled 6 Oct 2026, 13:53:36 UTC; Hoodi/mainnet dates not yet decided','9 月 17 日公告：Sepolia 计划 2026-10-06 13:53:36 UTC；Hoodi / 主网日期尚未确定'),t('ePBS and block-level access lists reorganize block production/validation to support L1 scaling; a testnet schedule is not mainnet activation','ePBS 与区块级访问列表重组出块 / 验证以支持 L1 扩容；测试网日程不等于主网激活'))])+p(t('The technical trend is parallel investment in L1 capacity and off-chain execution/payment networks. Lower data cost can broaden feasible applications, but actual user fees depend on demand, batching, prover/sequencer policy and congestion. This snapshot makes no live TPS, fee, adoption or market-share claims. Re-check the linked announcements before relying on a schedule.','技术趋势是同时投入 L1 容量与链下执行 / 支付网络。降低数据成本可扩大可行应用，但实际用户费用依需求、打包、证明器 / 排序器策略及拥堵而定。本快照不声称实时 TPS、费用、采用率或市场份额；依赖日程前应复核链接公告。')),('eth-history','eip4844','pectra','fusaka','taproot-08','glamsterdam'),'scale-updates')
    add('lightning-frontiers',t('Lightning is evolving in channel control, invoicing and assets','闪电网络在通道控制、发票及资产方面持续发展'),t('Each new feature requires matching protocol and implementation support.','每项新功能都需要对应协议及实现支持。'),p(t('Splicing changes a channel’s funding transaction to add or remove capacity while retaining the channel relationship, rather than treating every capacity change as an unrelated close/open cycle. BOLT 2 now documents its negotiation; verify the peers’ versions and feature negotiation instead of assuming support on every wallet. BOLT 12 offers add an offer → invoice request → invoice exchange using onion messages and blinded paths. An offer is not simply a reusable BOLT 11 payment invoice.','Splicing 改变通道注资交易以增减容量，同时保留通道关系，不再把每次容量改变都视为无关的关闭 / 重开。BOLT 2 已记录其协商流程；应核对双方版本及功能协商，不能假定所有钱包支持。BOLT 12 Offer 以洋葱消息及盲化路径加入 Offer → 发票请求 → 发票交换流程。Offer 不是简单可复用的 BOLT 11 支付发票。'),t('Taproot Assets commits asset state in Bitcoin Taproot outputs and validates asset lineage with additional client-side proofs. Asset-aware edge nodes can quote asset/BTC conversions through RFQ and route over BTC liquidity, so intermediate BTC routers need not all implement every asset. Bitcoin’s base consensus still validates Bitcoin transactions, not an issuer’s fiat reserves or every asset-level rule. Participants retain asset-proof storage/verification duties.','Taproot Assets 在 Bitcoin Taproot 输出中承诺资产状态，通过额外客户端证明验证资产沿革。识别资产的边缘节点可经 RFQ 报价完成资产 / BTC 转换并使用 BTC 流动性路由，中间 BTC 路由器不必全部实现每种资产。Bitcoin 底层共识仍验证 Bitcoin 交易，不验证发行方的法币储备或每项资产层规则。参与者仍负有资产证明保存 / 验证职责。'),t('The 2026 v0.8/SDK release is an implementation milestone for this model, not a declaration that all stablecoins, wallets or routes are available. Multi-asset payments retain issuer, redemption, pricing and edge liquidity dependencies. They expand the payment surface without turning Bitcoin into an Ethereum-style general EVM.','2026 年 v0.8 / SDK 发布是该模型的实现进展，不意味着所有稳定币、钱包或路径均可用。多资产支付仍依赖发行方、赎回、定价及边缘流动性。它们扩展支付能力，但没有把 Bitcoin 变成 Ethereum 式通用 EVM。')),('bolt2','bolt12','taproot-assets','taproot-rfq','taproot-08'))
    add('dimensions',t('Compare ecosystem effects through a trust and operations matrix','通过信任及运行矩阵比较生态影响'),t('Engineering interpretation: scaling changes costs, coordination and where power concentrates.','工程解读：扩容改变成本、协调方式及权力集中位置。'),table([t('Dimension','维度'),t('Ethereum rollup ecosystem','Ethereum Rollup 生态'),t('Lightning ecosystem','闪电网络生态')],[(t('Application surface','应用范围'),t('More affordable programmable applications; distinct chains divide liquidity and state','更低成本可编程应用；独立链分割流动性及状态'),t('Repeated small payments and payment integrations; channel liquidity constrains reachability','重复小额支付及支付集成；通道流动性约束可达性')),(t('Infrastructure roles','基础设施角色'),t('Sequencers, provers, DA archives and bridge/message operators','排序器、证明器、DA 归档及桥 / 消息运营者'),t('Routing nodes, liquidity services, watchtowers and asset edge nodes','路由节点、流动性服务、Watchtower 及资产边缘节点')),(t('Composability','可组合性'),t('Synchronous within one execution domain; cross-domain actions need explicit coordination','单执行域内同步，跨域动作需明确协调'),t('Payments compose across a route; this is not arbitrary shared contract storage','支付沿路径组合，不是任意共享合约存储')),(t('Control / exit','控制 / 退出'),t('Inspect proof and DA mode, upgrades, censorship fallback and withdrawal conditions','检查证明及 DA 模式、升级、抗审查后备路径及提现条件'),t('Inspect custody, latest state, liquidity, deadlines and unilateral-close conditions','检查托管、最新状态、流动性、期限及单边关闭条件')),(t('Measurement','测量'),t('Measure actual fee, batch/settlement lag and dependency failures','测量实际费用、批次 / 结算滞后及依赖故障'),t('Measure payment success, directional liquidity, routing fees and closure costs','测量支付成功率、方向流动性、路由费用及关闭成本'))])+p(t('For an application, draw who authorizes an action, who executes it, where its data lives, what makes it final and how the user exits during a failure. Compare these properties before ranking TPS. Faster networks can support new products while also concentrating control in sequencers, liquidity hubs or wallet providers. Decentralization must be evaluated across these roles, not inferred from a low fee or a protocol logo.','对应用画出谁授权动作、谁执行、数据在哪里、什么构成最终完成，以及故障时用户如何退出。比较这些性质，再考虑 TPS 排名。更快网络可支持新产品，也可能将控制集中于排序器、流动性枢纽或钱包提供商。应跨这些角色评估去中心化，不能从低费用或协议标志推断。')),('scaling','bridges','ln-liquidity','ln-recovery','web3'))
    return rows
